metrics.workdir_dsl:
workspace "Energy Manager" "C4 model of the home energy management platform" {

    model {

        homeowner = person "Homeowner" "A homeowner who uses the platform to manage the household's energy use and costs."

        energyManager = softwareSystem "Energy Manager" "A home energy management platform, owned and operated by our company, for managing household energy use and costs." {
            dashboard = container "Dashboard Web App" "A web app where homeowners see consumption and costs." "Web Application"
            scheduler = container "Scheduling Service" "A service that plans charging and heating." "Service"
            ratesLibrary = container "Rates Library" "A shared library that computes energy prices from tariff and time of day." "Software Library"
            database = container "Database" "A database that stores meter readings and schedules." "Database"
        }

        smartMeterProvider = softwareSystem "Smart Meter Provider" "An external system, operated by a different organization, that provides live meter readings." "External"

        homeowner -> dashboard "Manages household energy use and costs"
        dashboard -> ratesLibrary "Uses"
        scheduler -> ratesLibrary "Uses"
        scheduler -> smartMeterProvider "Fetches live meter readings"
        scheduler -> database "Stores meter readings and schedules"
    }

    views {
        systemContext energyManager "SystemContext" "A system context diagram of the Energy Manager platform." {
            include *
            autoLayout
        }

        container energyManager "Containers" "A container diagram of the Energy Manager platform." {
            include *
            autoLayout
        }
    }
}
